after.content:
for (const forbidden of [":ji-agent-", ":ji-session-", ":ji-provider-", ":ji-workspace-", ":ji-host-core", ":ji-host-sqlite"]) {
  if (relayBuild.includes(forbidden)) failures.push(`ji-relay-server depends on forbidden domain ${forbidden}`);
}
const protocolModules = [
  "ji-error-catalog", "ji-host-protocol", "ji-relay-protocol", "ji-acp-contract",
  "ji-acp-v1-server", "ji-acp-v2-preview-model", "ji-acp-v2-preview-server",
];
const approvedProtocolDependencies = new Set([
  "ji-acp-v2-preview-server:implementation:ji-acp-v2-preview-model",
  "ji-acp-v2-preview-server:testImplementation:ji-acp-v1-server",
]);
for (const moduleName of protocolModules) {
  const buildFile = path.join(root, "ji-java", "protocols", moduleName, "build.gradle.kts");
  const build = await readFile(buildFile, "utf8");
  const dependencies = build.matchAll(/\b(\w+)\s*\(project\(\":(ji-[^\"]+)"\)\)/g);
  for (const [, scope, dependency] of dependencies) {
    if (!protocolModules.includes(dependency)) continue;
    const edge = `${moduleName}:${scope}:${dependency}`;
    if (!approvedProtocolDependencies.has(edge)) {
      failures.push(`${moduleName} has unauthorized ${scope} dependency on protocol module ${dependency}`);
    }
  }
}
